pm.test("Health endpoint returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Application reports healthy status", function () {
    const response = pm.response.json();
    pm.expect(response.ok).to.eql(true);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

pm.test("Users endpoint returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is an array", function () {
    const users = pm.response.json();
    pm.expect(users).to.be.an("array");
});

pm.test("Users contain required properties", function () {
    const users = pm.response.json();

    pm.expect(users.length).to.be.above(0);

    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("username");
        pm.expect(user).to.have.property("email");
    });
});

pm.test("Valid login returns HTTP 303", function () {
    pm.response.to.have.status(303);
});

pm.test("Authentication cookie is issued", function () {
    const cookie = pm.response.headers.get("Set-Cookie");

    pm.expect(cookie).to.include("access_token=");
});

pm.test("Student is redirected to application", function () {
    const location = pm.response.headers.get("Location");

    pm.expect(location).to.match(/\/app\/?$/);
});

pm.test("Invalid login returns HTTP 303", function () {
    pm.response.to.have.status(303);
});

pm.test("Invalid login redirects to login page", function () {
    const location = pm.response.headers.get("Location");

    pm.expect(location).to.include("/login");
});

pm.test("No new authentication token is issued", function () {
    const cookie = pm.response.headers.get("Set-Cookie") || "";

    pm.expect(cookie).not.to.include("access_token=");
});

pm.test("Progress endpoint returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains HTML", function () {
    const contentType =
        pm.response.headers.get("Content-Type");

    pm.expect(contentType).to.include("text/html");
});

pm.test("Academic progress content is displayed", function () {
    pm.expect(pm.response.text())
        .to.include("Your academic overview");
});

pm.test("Unauthorized page is displayed", function () {
    pm.expect(pm.response.text())
        .to.include("Unauthorized");
});

pm.test("Student cannot view admin dashboard", function () {
    pm.expect(pm.response.text())
        .to.include("You do not have permission");
});
